/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

const Can_Lut_Sw_Entry * can_lut_sw_index (Can_Lut_Sw * const can_lut_sw , const UInt16 index)
{
  if (index < can_lut_sw->num_entries)
    {
      return can_lut_sw->table + index ;
    }
  else
    {
      return 0 ;
    }
}


